// LOT 2 — remplace le tableau `Config Sources KREDO` codé en dur.
// Lit `v_effective_watch_sources` (usage_scope=news) et normalise le contrat interne.
// Échec explicite si la vue ne renvoie rien : jamais de digest vide silencieux.
const rows = $input.all().map((i) => i.json);

if (!rows.length) {
  throw new Error(
    "v_effective_watch_sources (usage_scope=news) a retourné 0 ligne : run interrompu, aucun digest ne sera créé."
  );
}

const sorted = [...rows].sort((a, b) => {
  const pa = a.priority ?? 0;
  const pb = b.priority ?? 0;
  if (pa !== pb) return pa - pb;
  return (b.utility_score ?? 0) - (a.utility_score ?? 0);
});

const sources = sorted.map((r) => ({
  sourceId: r.source_id,
  sourceKey: r.source_key,
  sourceName: r.source_name,
  publisher: r.publisher,
  domain: r.domain,
  searchDomain: r.search_domain,
  collectionUrl: r.collection_url,
  collectionMode: r.collection_mode,
  family: r.family,
  kredoCategory: r.kredo_category,
  origin: r.origin,
  corpusId: r.corpus_id,
}));

return [{ json: { sources } }];

// Dérive l'URL de collecte réelle depuis le mode livré par la vue.
// rss   -> flux direct (collectionUrl).
// site_search -> Google News RSS restreint au domaine, requête simple site:<search_domain>.
const s = $json;
const mode = s.collectionMode === "rss" && s.collectionUrl ? "rss" : "site_search";
const feedUrl =
  mode === "rss"
    ? s.collectionUrl
    : `https://news.google.com/rss/search?q=site:${encodeURIComponent(s.searchDomain)}&hl=fr&gl=FR&ceid=FR:fr`;

return { json: { ...s, collectionMode: mode, feedUrl } };

// Branche `site_search` — parse la réponse texte brute de Google News RSS.
// Volontairement un regex simple sur des <item> XML plutôt qu'un parseur XML complet :
// le flux est propre, généré par Google, et le besoin est de rester "robuste et simple"
// (pas de scraping massif). Déballe l'éditeur réel depuis <source url="…">Nom</source>
// pour ne jamais écrire news.google.com comme provenance finale.
const first = $input.first().json;
const xml = typeof first === "string" ? first : first.data ?? first.body ?? "";

function pick(tag, block) {
  const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, "i"));
  return m ? m[1].trim() : null;
}

function stripCdata(s) {
  if (!s) return s;
  const m = s.match(/^<!\[CDATA\[([\s\S]*)\]\]>$/);
  return m ? m[1] : s;
}

function decodeEntities(s) {
  if (!s) return s;
  return s
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

const itemBlocks = xml.match(/<item>[\s\S]*?<\/item>/g) || [];

const items = itemBlocks
  .map((block) => {
    const title = decodeEntities(stripCdata(pick("title", block)));
    const link = decodeEntities(stripCdata(pick("link", block)));
    const pubDate = pick("pubDate", block);
    const description = decodeEntities(stripCdata(pick("description", block)));
    const sourceMatch = block.match(/<source[^>]*url="([^"]*)"[^>]*>([\s\S]*?)<\/source>/i);
    const realPublisher = sourceMatch ? decodeEntities(stripCdata(sourceMatch[2])) : null;
    const realPublisherUrl = sourceMatch ? sourceMatch[1] : null;

    return {
      title,
      link,
      pubDate,
      contentSnippet: description,
      realPublisher,
      realPublisherUrl,
      collectedVia: "google_news_site_search",
    };
  })
  .filter((i) => i.title && i.link);

// IMPORTANT : ne jamais retourner un tableau vide ici, même quand la recherche
// site: ne remonte légitimement aucun résultat (domaine mal indexé par Google
// News). Comme pour « Ignorer Source En Erreur », n8n arrête l'exécution du
// workflow entier — et donc la boucle sur les sources suivantes — quand un
// nœud ne produit aucun item en sortie. Un item factice sans title/link est
// filtré naturellement par le préfiltre de qualité en aval (`Dédup + Filtre
// Récence + Préfiltre Qualité` exige `a.link && a.title`), sans jamais devenir
// un candidat.
if (items.length === 0) {
  return [
    {
      json: {
        title: null,
        link: null,
        pubDate: null,
        contentSnippet: null,
        realPublisher: null,
        realPublisherUrl: null,
        collectedVia: "google_news_site_search",
        noResults: true,
      },
    },
  ];
}

return items.map((json) => ({ json }));

// Commun aux deux branches (rss / site_search). En site_search, préfère l'éditeur réel
// déballé par « Parser Flux Google News » : ne jamais écrire news.google.com comme source.
const source = $("Loop Over Items — 1 Source").item.json;
const item = $json;

const isSiteSearch = source.collectionMode !== "rss";
const publisher = isSiteSearch
  ? item.realPublisher || source.publisher || source.sourceName
  : source.publisher || source.sourceName;

return {
  json: {
    title: item.title || "",
    link: item.link || "",
    pubDate: item.pubDate || item.isoDate || null,
    contentSnippet: item.contentSnippet || item.content || "",
    sourceName: publisher,
    sourceId: source.sourceId,
    sourceKey: source.sourceKey,
    sourceHomepage: source.searchDomain,
    family: source.family,
    categorieDefaut: source.kredoCategory,
    secteurDefaut: "transverse",
    collectedVia: item.collectedVia || (isSiteSearch ? "google_news_site_search" : "rss_direct"),
  },
};

const source = $("Loop Over Items — 1 Source").item.json;
const err = $input.first().json.error || $input.first().json;
const cible = source.collectionUrl || source.searchDomain || "url inconnue";

console.log(
  `[Veille KREDO] Flux en erreur, source ignorée : ${source.sourceName} (${cible}) — ${JSON.stringify(err).slice(0, 300)}`
);

// IMPORTANT : ne jamais retourner un tableau vide ici. n8n arrête l'exécution
// du workflow entier quand un nœud ne produit aucun item en sortie (sauf à
// activer 'Always Output Data' dans les Settings du nœud). On retourne donc
// un item factice pour que la boucle B3 reçoive un signal et continue vers
// la source suivante.
return [{ json: { skipped: true, sourceName: source.sourceName, sourceUrl: cible } }];

// TOURNIQUET PAR SOURCE — remplace un `slice(0, 40)` POSITIONNEL.
//
// Les items arrivent ici dans l'ordre de la boucle sur les sources. Les 4 digests
// produits sont tous a 40/40 candidats pour 14 sources : le plafond etait sature,
// les dernieres sources du tableau ne contribuaient DEJA rien, et toute source
// ajoutee (manuelle ou issue d'un corpus) produisait exactement zero candidat
// supplementaire — sans erreur, sans log, sans trace.
// Meme correctif que `Normalize & Dedup Items` d'INTEL-033, mais clé PAR SOURCE
// et non par famille : une famille unique ecraserait ses propres sources.
//
// LOT 2 — la clé se re-clé désormais sur `sourceId` (uuid de `source_catalog`),
// avec fallback `sourceKey` puis `sourceName` pour robustesse uniquement — jamais
// un cap positionnel.
const seenRows = $("Récupérer Hash Articles Vus").all().map((i) => i.json);
const seenHashes = new Set(seenRows.map((r) => r.url_hash));

const MAX_CANDIDATS = 40;
const FENETRE_JOURS = 7;

const now = new Date();
const debutFenetre = new Date(now.getTime() - FENETRE_JOURS * 24 * 60 * 60 * 1000);

const bruts = $input.all().map((i) => i.json);

// Les items { skipped: true } viennent de « Ignorer Source En Erreur », qui
// reinjecte la boucle sans porter d'article. Ils comptent comme source en
// erreur, jamais comme candidat.
const sourcesEnErreur = new Set(
  bruts.filter((a) => a.skipped && a.sourceName).map((a) => a.sourceName)
);

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return String(hash);
}

// Dedup douce : un meme evenement (depeche, communique) est repris a l'identique
// par plusieurs editeurs. Sans le tourniquet le probleme etait invisible — 3
// sources se partageaient les 40 places. Avec 14 sources qui contribuent, le
// meme titre pourrait consommer 3 places sur 40. Comparaison sur titre EXACT
// normalise seulement : deux angles differents restent deux candidats distincts.
function normaliserTitre(t) {
  return (t || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

// `pubDate` peut etre absente ou non parsable : on renvoie 0 plutot que NaN,
// qui rendrait le comparateur de tri incoherent.
function instant(valeur) {
  if (!valeur) return 0;
  const d = new Date(valeur);
  const t = d.getTime();
  return Number.isNaN(t) ? 0 : t;
}

const filtres = bruts
  .filter((a) => a.link && a.title)
  .map((a) => ({ ...a, urlHash: simpleHash(a.link) }))
  .filter((a) => !seenHashes.has(a.urlHash))
  .filter((a) => {
    if (!a.pubDate) return true; // pas de date fiable : on laisse le classement IA trancher
    const t = instant(a.pubDate);
    return t === 0 || t >= debutFenetre.getTime();
  })
  .filter((a) => (a.title || "").length > 10);

const vusHash = new Set();
const vusTitre = new Set();
const retenus = [];
for (const a of filtres) {
  if (vusHash.has(a.urlHash)) continue;
  const cleTitre = normaliserTitre(a.title);
  if (cleTitre && vusTitre.has(cleTitre)) continue;
  vusHash.add(a.urlHash);
  if (cleTitre) vusTitre.add(cleTitre);
  retenus.push(a);
}

// Une file par source, triee par fraicheur decroissante, puis service en
// tourniquet jusqu'au plafond. Clé primaire `sourceId` (uuid `source_catalog`,
// stable et unique) ; `sourceKey` puis `sourceName` restent en fallback de
// robustesse seulement — jamais un cap positionnel.
function cleSource(a) {
  return a.sourceId || a.sourceKey || a.sourceName || "source_inconnue";
}

const parSource = new Map();
for (const a of retenus) {
  const cle = cleSource(a);
  if (!parSource.has(cle)) parSource.set(cle, []);
  parSource.get(cle).push(a);
}
for (const file of parSource.values()) {
  file.sort((x, y) => instant(y.pubDate) - instant(x.pubDate));
}

const files = Array.from(parSource.values());
const plafonnes = [];
let progres = true;
while (plafonnes.length < MAX_CANDIDATS && progres) {
  progres = false;
  for (const file of files) {
    if (file.length === 0) continue;
    plafonnes.push(file.shift());
    progres = true;
    if (plafonnes.length >= MAX_CANDIDATS) break;
  }
}

// Metriques de run, identiques sur chaque item : « Créer Digest » les lit via
// `.first()`. `sourcesContributrices` est la seule mesure honnete de l'etendue
// reelle de la collecte.
const sourcesContributrices = new Set(plafonnes.map(cleSource)).size;
const sourcesChargees = new Set(bruts.filter((a) => a.sourceName).map((a) => cleSource(a))).size;

return plafonnes.map((a, idx) => ({
  json: {
    id: `art_${idx}`,
    title: a.title,
    source: a.sourceName,
    sourceCatalogId: a.sourceId || null,
    roundRobinKey: cleSource(a),
    url: a.link,
    urlHash: a.urlHash,
    publishedAt: a.pubDate,
    summary: (a.contentSnippet || "").slice(0, 600),
    secteurDefaut: a.secteurDefaut,
    categorieDefaut: a.categorieDefaut,
    collectedVia: a.collectedVia || null,
    sourcesChargees,
    sourcesContributrices,
    sourcesEnErreur: sourcesEnErreur.size,
    candidatsAvantPlafond: retenus.length,
  },
}));

const items = $input.all().map(i => i.json);
const blocContexteKredo = $('Build Contexte KREDO').first().json.blocContexteKredo;
const secteursActifs = $('Build Contexte KREDO').first().json.secteursActifs;
const dateRun = new Date().toISOString().slice(0, 10);

const articlesBlock = items.map(a =>
  `id: ${a.id}\ntitre: ${a.title}\nsource: ${a.source}\ndate: ${a.publishedAt || 'inconnue'}\nchapo: ${a.summary}`
).join('\n\n---\n\n');

const promptClassement = `${blocContexteKredo}

# TÂCHE
Voici une liste d'articles candidats de la semaine. Évalue CHACUN selon la grille
ci-dessous, puis renvoie jusqu'à 5 articles classés par score décroissant.

Tu peux retourner moins de 5 articles si le nombre de candidats ou leur qualité
ne justifie pas une sélection complète.

Si AUCUN article ne constitue une munition commerciale suffisamment exploitable,
retourne exactement :

{"top5":[]}

N'invente jamais un article ou un identifiant.

# FILTRE PRÉALABLE OBLIGATOIRE
Date de référence : ${dateRun}.
Écarte immédiatement, avant tout scoring, tout article publié il y a plus de 7 jours.
La veille est HEBDOMADAIRE : un article ancien n'a pas sa place, même s'il est bon.

# GRILLE DE SCORING (0 à 100)
- Actionnabilité commerciale (0-40) : l'article fournit-il un angle, un déclencheur
  ou un argument qu'un commercial peut réellement utiliser ? (le critère roi)
- Pertinence pour le lecteur ESN (0-25) : parle-t-il d'IA appliquée, de tendance
  décideur, de réglementation créatrice de besoin ?
- Alignement secteur KREDO (0-20) : touche-t-il un secteur de ${secteursActifs} ?
  (0 si transverse, mais un article transverse fort reste éligible)
- Crédibilité & fraîcheur (0-15) : source fiable, information récente et non éculée.
- PÉNALITÉS : retire des points pour buzz creux, technique non traduit, doublon
  thématique évident, contenu promotionnel.

# CONTRAINTE DE DIVERSITÉ
À pertinence comparable, privilégie la diversité des catégories et des secteurs dans
le top 5. Évite de retenir 5 articles de la même catégorie ou du même acteur.

# FORMAT DE SORTIE
Réponds UNIQUEMENT avec un JSON valide, une seule ligne, sans backticks, sans aucun texte
avant ou après, structure exacte :
{"top5":[{"id":"art_0","score":87,"categorie":"ia-appliquee","secteur_principal":"banque-finance","secteur_secondaire":"","justification":"..."}]}

# ARTICLES CANDIDATS
${articlesBlock}`;

return [{
  json: {
    promptClassement,
    candidatesById: Object.fromEntries(items.map(a => [a.id, a])),
  }
}];

const response = $input.first().json;
const textBlock = (response.content || []).find(b => b.type === 'text');
const rawText = textBlock?.text || '';
const promptNodeJson = $('Construire Prompt Classement').first().json;
const candidatesById = promptNodeJson.candidatesById || {};
const candidateCount = Object.keys(candidatesById).length;

function extractJson(text) {
  const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced) return fenced[1].trim();
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) return text.slice(first, last + 1);
  return text;
}

let parsed;
try {
  parsed = JSON.parse(extractJson(rawText));
} catch (e) {
  throw new Error('Le classement Haiku n a pas renvoye un JSON exploitable : ' + rawText.slice(0, 300));
}

if (!parsed || !Array.isArray(parsed.top5)) {
  throw new Error('Le classement Haiku n a pas renvoye un objet avec la cle top5 : ' + rawText.slice(0, 300));
}

const top5 = (parsed.top5 || []).slice(0, 5).map(t => {
  if (!t || typeof t !== 'object' || !t.id) return null;
  const candidate = candidatesById[t.id];
  if (!candidate) return null;
  return {
    ...candidate,
    score: t.score,
    categorie: t.categorie || candidate.categorieDefaut,
    secteurPrincipal: t.secteur_principal || candidate.secteurDefaut,
    secteurSecondaire: t.secteur_secondaire || '',
    justification: t.justification || '',
  };
}).filter(Boolean);

if (top5.length === 0) {
  return [
    {
      json: {
        emptySelection: true,
        status: "no_qualifying_articles",
        candidateCount,
        selectedCount: 0,
        digestUpdated: false,
      },
    },
  ];
}

return top5.map(a => ({ json: a }));

const response = $input.first().json;
const textBlock = (response.content || []).find((b) => b.type === "text");
const rawText = textBlock?.text || "";
const sourceArticles = $("Construire Prompt Analyse").first().json.sourceArticles;

function extractJson(text) {
  const fenced = text.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  if (fenced) return fenced[1].trim();
  const first = text.indexOf("{");
  const last = text.lastIndexOf("}");
  if (first >= 0 && last > first) return text.slice(first, last + 1);
  return text;
}

function repair(text) {
  return text
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/,\s*([}\]])/g, "$1");
}

let parsed;
try {
  parsed = JSON.parse(repair(extractJson(rawText)));
} catch (e) {
  throw new Error("L analyse Sonnet n a pas renvoye un JSON exploitable : " + rawText.slice(0, 300));
}

// Clé stable : on relie chaque article renvoyé par le LLM à sa source via son
// `id` (art_0, art_1…), pas via la position dans le tableau — le contrat LLM
// n'est pas garanti de préserver l'ordre ou le compte exact. Fallback sur
// l'index uniquement si le modèle a omis le champ `id`.
const byId = Object.fromEntries(sourceArticles.map((a) => [a.id, a]));

const articles = (parsed.articles || []).map((a, idx) => {
  const src = byId[a.id] || sourceArticles[idx] || {};
  return {
    selectionRank: a.selection_rank || idx + 1,
    titreFr: a.titre_fr,
    resume: a.resume,
    analyseKredo: a.analyse_kredo,
    actionCommerciale: a.action_commerciale,
    secteurPrincipal: a.secteur_principal || src.secteurPrincipal || "transverse",
    secteurSecondaire: a.secteur_secondaire || "",
    categorie: a.categorie || src.categorie,
    tags: a.tags || [],
    convergences: a.convergences,
    url: src.url,
    urlHash: src.urlHash,
    sourceName: src.source,
    sourceCatalogId: src.sourceCatalogId || null,
    collectedVia: src.collectedVia || null,
    publishedAt: src.publishedAt || null,
  };
});

return [
  {
    json: {
      titreDigest: parsed.titre_digest,
      resumeHebdo: parsed.resume_hebdo,
      superShortSummary: parsed.super_short_summary,
      articles,
    },
  },
];

const digest = $("Valider Convergences").first().json;
const digestRow = $("Créer Digest").first().json;
const workspaceId = $("Build Contexte KREDO").first().json.workspaceId;

const p_articles = digest.articles.map((a) => ({
  digest_id: digestRow.id,
  workspace_id: workspaceId,
  selection_rank: a.selectionRank,
  titre_fr: a.titreFr,
  source_name: a.sourceName,
  source_catalog_id: a.sourceCatalogId,
  url: a.url,
  url_hash: a.urlHash,
  published_at: a.publishedAt,
  resume: a.resume,
  analyse_kredo: a.analyseKredo,
  action_commerciale: a.actionCommerciale,
  secteur_principal: a.secteurPrincipal,
  secteur_secondaire: a.secteurSecondaire,
  categorie: a.categorie,
  tags: a.tags,
  convergences: a.convergences,
}));

return [
  {
    json: {
      p_digest_id: digestRow.id,
      p_articles,
    },
  },
];

// Instrumentation Lot 6 — calcul des métriques de collecte par source pour la veille hebdo.
const loadedSources = $('Charger Sources Effectives (Supabase)').all().map((i) => i.json).filter((s) => s && s.source_id);
const enrichedItems = $('Enrichir avec Métadonnées Source').all().map((i) => i.json).filter((it) => it && it.sourceId);
const errorItems = $('Ignorer Source En Erreur').all().map((i) => i.json).filter((it) => it && it.sourceId && it.error);
const dedupCandidateItems = $('Dédup + Filtre Récence + Préfiltre Qualité').all().map((i) => i.json).filter((it) => it && (it.sourceId || it.source_id));
const retainedArticles = $('Préparer Lignes Articles').all().map((i) => i.json).filter((a) => a && (a.source_catalog_id || a.sourceId));

const runKey = typeof $execution !== 'undefined' && $execution && $execution.id ? $execution.id : ('run-' + Date.now());

const failedSourceIds = new Set(errorItems.map((it) => it.sourceId));

const collectedBySource = new Map();
for (const it of enrichedItems) {
  if (it.placeholder) continue;
  const sId = it.sourceId;
  collectedBySource.set(sId, (collectedBySource.get(sId) || 0) + 1);
}

const dedupBySource = new Map();
for (const it of dedupCandidateItems) {
  const sId = it.sourceId || it.source_id;
  if (!sId) continue;
  dedupBySource.set(sId, (dedupBySource.get(sId) || 0) + 1);
}

const retainedBySource = new Map();
for (const a of retainedArticles) {
  const sId = a.source_catalog_id || a.sourceId;
  if (!sId) continue;
  retainedBySource.set(sId, (retainedBySource.get(sId) || 0) + 1);
}

const metrics = loadedSources.map((s) => {
  const sourceCatalogId = s.source_id;
  const corpusId = s.corpus_id || null;
  const isError = failedSourceIds.has(sourceCatalogId);
  const querySucceeded = !isError;
  const itemsCollected = querySucceeded ? (collectedBySource.get(sourceCatalogId) || 0) : 0;
  const itemsAfterDedup = dedupBySource.get(sourceCatalogId) || 0;
  const itemsRetained = retainedBySource.get(sourceCatalogId) || 0;

  return {
    source_catalog_id: sourceCatalogId,
    corpus_id: corpusId,
    workflow_id: 'veille-hebdomadaire-kredo',
    workflow_run_key: runKey,
    usage_scope: 'news',
    company_id: null,
    query_succeeded: querySucceeded,
    items_collected: itemsCollected,
    items_after_dedup: itemsAfterDedup,
    items_retained: itemsRetained,
  };
});

if (metrics.length === 0) {
  return [];
}

return metrics.map((m) => ({ json: m }));

// LOT 3 (Convergences transverses) — pré-filtrage déterministe multi-gisement.
// Étend le LOT 2.1 (comptes + enjeux + playbooks) à account_signals, account_facts
// et opportunities. Rien ne quitte ce nœud sans borne stricte, par article :
// 8 comptes, 3 enjeux, 10 signaux, 15 faits, 3 opportunités, 3 playbooks utiles.
// Le ranking est un simple overlap de mots-clés + fraîcheur + scores déjà stockés en
// base (global_score, confidence_score, importance/urgency/criticality/business_impact) :
// aucun LLM, aucun pgvector, aucun RAG.
const top5 = $('Parser Top 5').all().map(i => i.json);
const comptes = $('Charger Comptes').all().map(i => i.json);
const enjeux = $('Charger Enjeux').all().map(i => i.json);
const playbooks = $('Charger Playbooks').all().map(i => i.json);
const signaux = $('Charger Signaux Comptes').all().map(i => i.json);
const faits = $('Charger Faits Comptes').all().map(i => i.json);
const opportunites = $('Charger Opportunités').all().map(i => i.json);

const BORNES = {
  MAX_COMPTES: 8,
  MAX_ISSUES: 3,
  MAX_SIGNAUX: 10,
  MAX_FAITS: 15,
  MAX_OPPORTUNITES: 3,
  MAX_PLAYBOOKS: 3,
};

// Longueur minimale 2 (pas 3) : le vocabulaire du domaine regorge d'acronymes courts
// et centraux (IA, 5G, DSI, ...). Les mots grammaticaux courts sont filtrés
// explicitement via cette liste plutôt que par une coupe de longueur aveugle.
const STOPWORDS = new Set([
  'les', 'des', 'dans', 'pour', 'avec', 'sur', 'une', 'un', 'le', 'la', 'de', 'du',
  'et', 'en', 'au', 'aux', 'par', 'ce', 'ces', 'son', 'sa', 'ses', 'qui', 'que',
  'est', 'sont', 'plus', 'vers', 'sans', 'sous', 'ou', 'a', 'the', 'and', 'for',
  'il', 'elle', 'on', 'ne', 'pas', 'se', 'ca', 'ci', 'là', 'da', 'di', 'du',
]);

function normalizeStr(str) {
  if (!str) return '';
  return String(str)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function tokenize(text) {
  const norm = normalizeStr(text);
  if (!norm) return [];
  return norm.split(' ').filter((t) => t.length >= 2 && !STOPWORDS.has(t));
}

function tokenSet(text) {
  return new Set(tokenize(text));
}

// Overlap simple (nombre de tokens signifiants partagés) : suffisant pour un
// pré-filtrage borné et déterministe, pas besoin de tf-idf ni d'embeddings.
function overlapScore(setA, setB) {
  if (!setA.size || !setB.size) return 0;
  let shared = 0;
  for (const t of setA) if (setB.has(t)) shared += 1;
  return shared;
}

function daysSince(dateStr) {
  if (!dateStr) return null;
  const t = new Date(dateStr).getTime();
  if (Number.isNaN(t)) return null;
  return (Date.now() - t) / (24 * 60 * 60 * 1000);
}

function freshnessBonus(dateStr, halfLifeDays) {
  const d = daysSince(dateStr);
  if (d === null || d < 0) return 0;
  return Math.max(0, 1 - d / halfLifeDays);
}

const FACT_TYPE_PRIORITY = new Set([
  'strategic_priority', 'transformation_program', 'technology',
  'growth_trend', 'market_position', 'differentiators',
]);

// Un playbook squelette de seed ({personas:[],objections:[],entry_points:[],roi_arguments:[]})
// n'est PAS utile : toutes ses clés sont des tableaux vides. `{}` non plus.
function playbookIsUseful(playbook) {
  if (!playbook || typeof playbook !== 'object') return false;
  return Object.values(playbook).some((v) => {
    if (Array.isArray(v)) return v.length > 0;
    if (typeof v === 'string') return v.trim().length > 0;
    return !!v;
  });
}

function playbookText(playbook) {
  if (!playbook || typeof playbook !== 'object') return '';
  return Object.values(playbook)
    .map((v) => {
      if (Array.isArray(v)) return v.map((x) => (typeof x === 'string' ? x : JSON.stringify(x))).join(' ');
      if (typeof v === 'string') return v;
      return '';
    })
    .join(' ');
}

// --- Taxonomie relationnelle (reprise à l'identique du LOT 2.1) ---
const macroIndex = new Map();
const segmentIndex = new Map();

for (const p of playbooks) {
  if (p.macro_id) {
    if (!macroIndex.has(p.macro_id)) {
      macroIndex.set(p.macro_id, {
        id: p.macro_id,
        name: p.macro_name || '',
        normName: normalizeStr(p.macro_name),
        segmentIds: new Set(),
      });
    }
    if (p.segment_id) macroIndex.get(p.macro_id).segmentIds.add(p.segment_id);
  }
  if (p.segment_id) {
    segmentIndex.set(p.segment_id, {
      id: p.segment_id,
      name: p.segment_name || '',
      normName: normalizeStr(p.segment_name),
      macroId: p.macro_id || null,
      playbook: p.playbook,
    });
  }
}

const companyNameById = new Map(comptes.map((c) => [c.id, c.name || '']));

function resolveSectors(rawSector) {
  const resolvedMacroIds = new Set();
  const resolvedSegmentIds = new Set();

  if (!rawSector) return { resolvedMacroIds, resolvedSegmentIds };
  const nTarget = normalizeStr(rawSector);
  if (!nTarget || nTarget === 'transverse') return { resolvedMacroIds, resolvedSegmentIds };

  let exactMatch = false;

  for (const macro of macroIndex.values()) {
    if (macro.normName === nTarget) {
      resolvedMacroIds.add(macro.id);
      macro.segmentIds.forEach((segId) => resolvedSegmentIds.add(segId));
      exactMatch = true;
    }
  }
  for (const seg of segmentIndex.values()) {
    if (seg.normName === nTarget) {
      resolvedSegmentIds.add(seg.id);
      if (seg.macroId) resolvedMacroIds.add(seg.macroId);
      exactMatch = true;
    }
  }

  if (exactMatch) return { resolvedMacroIds, resolvedSegmentIds };

  for (const macro of macroIndex.values()) {
    if (macro.normName && (macro.normName.includes(nTarget) || nTarget.includes(macro.normName) || macro.normName.startsWith(nTarget))) {
      resolvedMacroIds.add(macro.id);
      macro.segmentIds.forEach((segId) => resolvedSegmentIds.add(segId));
    }
  }
  for (const seg of segmentIndex.values()) {
    if (seg.normName && (seg.normName.includes(nTarget) || nTarget.includes(seg.normName) || seg.normName.startsWith(nTarget))) {
      resolvedSegmentIds.add(seg.id);
      if (seg.macroId) resolvedMacroIds.add(seg.macroId);
    }
  }

  return { resolvedMacroIds, resolvedSegmentIds };
}

// --- Index des gisements par compte ---
function indexBy(rows, keyFn) {
  const map = new Map();
  for (const row of rows) {
    const key = keyFn(row);
    if (!key) continue;
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(row);
  }
  return map;
}

const signauxParCompte = indexBy(signaux, (s) => s.company_id);
const faitsParCompte = indexBy(faits, (f) => f.target_id);
const issuesParCompte = indexBy(enjeux, (e) => e.company_id);
const oppsParCompte = indexBy(opportunites, (o) => o.company_id);

function topN(scoredItems, n) {
  return scoredItems
    .slice()
    .sort((a, b) => b.score - a.score)
    .slice(0, n)
    .map((x) => x.item);
}

const output = top5.map((article) => {
  const sPrincipal = article.secteurPrincipal || article.secteur_principal || '';
  const sSecondaire = article.secteurSecondaire || article.secteur_secondaire || '';

  const resPrincipal = resolveSectors(sPrincipal);
  const resSecondaire = resolveSectors(sSecondaire);
  const allResolvedMacroIds = new Set([...resPrincipal.resolvedMacroIds, ...resSecondaire.resolvedMacroIds]);
  const allResolvedSegmentIds = new Set([...resPrincipal.resolvedSegmentIds, ...resSecondaire.resolvedSegmentIds]);
  const isTransverse = allResolvedMacroIds.size === 0 && allResolvedSegmentIds.size === 0;

  // Pool de comptes candidats : filtré par secteur/segment résolu, ou l'ensemble si transverse.
  const pool = isTransverse
    ? comptes
    : comptes.filter((c) => (c.sector_id && allResolvedMacroIds.has(c.sector_id)) || (c.segment_id && allResolvedSegmentIds.has(c.segment_id)));

  // Tokens de l'article : titre + chapô + justification éventuelle du classement Haiku.
  const articleText = [article.title, article.summary, article.justification].filter(Boolean).join(' ');
  const articleTokens = tokenSet(articleText);

  function scoreSignal(s) {
    const text = [s.title, s.summary].filter(Boolean).join(' ');
    const overlap = overlapScore(articleTokens, tokenSet(text));
    const fresh = freshnessBonus(s.detected_at, 60);
    const scoreBrut = Number(s.global_score) || Number(s.relevance_score) || 0;
    return overlap * 3 + fresh * 2 + scoreBrut * 2;
  }

  function scoreFact(f) {
    const text = f.value_text || (f.value_json ? JSON.stringify(f.value_json) : '');
    const overlap = overlapScore(articleTokens, tokenSet(text));
    const typeBonus = FACT_TYPE_PRIORITY.has(f.fact_type) ? 1.5 : 0;
    const confBonus = Number(f.confidence_score) || 0;
    return overlap * 3 + typeBonus + confBonus;
  }

  function scoreIssue(e) {
    const text = [e.title, e.problem_statement].filter(Boolean).join(' ');
    const overlap = overlapScore(articleTokens, tokenSet(text));
    const importance = ((e.importance || 0) + (e.urgency || 0) + (e.criticality || 0) + (e.business_impact || 0)) / 4 / 10;
    return overlap * 3 + importance;
  }

  function scoreOpportunity(o) {
    const text = [o.title, o.need_summary].filter(Boolean).join(' ');
    const overlap = overlapScore(articleTokens, tokenSet(text));
    const isOpen = o.stage !== 'gagne';
    return overlap * 3 + (isOpen ? 1 : 0.3);
  }

  const accountScored = pool.map((c) => {
    const sSig = (signauxParCompte.get(c.id) || []).map((s) => ({ item: s, score: scoreSignal(s) }));
    const sFait = (faitsParCompte.get(c.id) || []).map((f) => ({ item: f, score: scoreFact(f) }));
    const sIssue = (issuesParCompte.get(c.id) || []).map((e) => ({ item: e, score: scoreIssue(e) }));
    const sOpp = (oppsParCompte.get(c.id) || []).map((o) => ({ item: o, score: scoreOpportunity(o) }));
    // Score de compte = somme des 3 meilleurs items tous gisements confondus :
    // favorise un compte avec UNE preuve forte plutôt qu'une accumulation de bruit.
    const bestScores = [...sSig, ...sFait, ...sIssue, ...sOpp]
      .map((x) => x.score)
      .sort((a, b) => b - a)
      .slice(0, 3);
    const companyScore = bestScores.reduce((a, b) => a + b, 0);
    return { company: c, companyScore, sSig, sFait, sIssue, sOpp };
  });

  accountScored.sort((a, b) => b.companyScore - a.companyScore || a.company.name.localeCompare(b.company.name));
  const retainedAccounts = accountScored.slice(0, BORNES.MAX_COMPTES);

  const candidateSignals = topN(retainedAccounts.flatMap((a) => a.sSig), BORNES.MAX_SIGNAUX).map((s) => ({
    id: s.id,
    company_id: s.company_id,
    company_name: companyNameById.get(s.company_id) || '',
    signal_category: s.signal_category,
    signal_type: s.signal_type,
    title: s.title,
    summary: s.summary || '',
    event_at: s.event_at || null,
    detected_at: s.detected_at,
    global_score: s.global_score,
    relevance_score: s.relevance_score,
    recommended_action: s.recommended_action || null,
  }));

  const candidateFacts = topN(retainedAccounts.flatMap((a) => a.sFait), BORNES.MAX_FAITS).map((f) => ({
    id: f.id,
    company_id: f.target_id,
    company_name: companyNameById.get(f.target_id) || '',
    fact_type: f.fact_type,
    fact_subtype: f.fact_subtype || null,
    value: f.value_text || f.value_json || null,
    confidence_score: f.confidence_score,
    effective_at: f.effective_at || null,
  }));

  const candidateIssues = topN(retainedAccounts.flatMap((a) => a.sIssue), BORNES.MAX_ISSUES).map((e) => ({
    id: e.id,
    company_id: e.company_id,
    company_name: companyNameById.get(e.company_id) || '',
    title: e.title || '',
    problem_statement: e.problem_statement || '',
  }));

  const candidateOpportunities = topN(retainedAccounts.flatMap((a) => a.sOpp), BORNES.MAX_OPPORTUNITES).map((o) => ({
    id: o.id,
    company_id: o.company_id,
    company_name: companyNameById.get(o.company_id) || '',
    title: o.title,
    stage: o.stage,
    isOpen: o.stage !== 'gagne',
    opportunity_type: o.opportunity_type || null,
  }));

  let playbookPool;
  if (isTransverse) {
    playbookPool = playbooks;
  } else {
    playbookPool = playbooks.filter((p) => (p.segment_id && allResolvedSegmentIds.has(p.segment_id)) || (p.macro_id && allResolvedMacroIds.has(p.macro_id)));
  }

  const candidatePlaybooks = playbookPool
    .filter((p) => playbookIsUseful(p.playbook))
    .map((p) => ({ p, score: overlapScore(articleTokens, tokenSet(playbookText(p.playbook))) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, BORNES.MAX_PLAYBOOKS)
    .map(({ p }) => ({
      sector_id: p.segment_id,
      segment_id: p.segment_id,
      segment_name: p.segment_name,
      macro_id: p.macro_id,
      macro_name: p.macro_name,
      playbook: p.playbook,
    }));

  const candidateAccounts = retainedAccounts.map((a) => ({
    id: a.company.id,
    name: a.company.name,
    sector_id: a.company.sector_id,
    segment_id: a.company.segment_id,
    lifecycle_status: a.company.lifecycle_status,
  }));

  const allResolvedIds = [...allResolvedMacroIds, ...allResolvedSegmentIds];

  return {
    json: {
      ...article,
      convergenceContext: {
        candidateAccounts,
        candidateIssues,
        candidateSignals,
        candidateFacts,
        candidateOpportunities,
        candidatePlaybooks,
      },
      // Jamais persisté dans veille_articles — « Préparer Lignes Articles » ne lit que
      // `a.convergences` (sortie Sonnet validée), pas ce champ. Inspectable uniquement
      // dans la sortie du nœud n8n pour diagnostiquer un run.
      convergenceDebug: {
        secteurPrincipal: sPrincipal,
        secteurSecondaire: sSecondaire,
        resolvedSectorIds: allResolvedIds,
        candidateAccountsCount: candidateAccounts.length,
        candidateIssuesCount: candidateIssues.length,
        candidateSignalsCount: candidateSignals.length,
        candidateFactsCount: candidateFacts.length,
        candidateOpportunitiesCount: candidateOpportunities.length,
        candidatePlaybooksCount: candidatePlaybooks.length,
        topAccounts: retainedAccounts.slice(0, 5).map((a) => ({
          id: a.company.id,
          name: a.company.name,
          score: Math.round(a.companyScore * 100) / 100,
        })),
      },
    },
  };
});

return output;

// LOT 3 (Convergences transverses) — Validation déterministe & anti-hallucination.
// Étend le LOT 2.2 : mêmes garde-fous (matchedIssues, relatedAccounts, playbookSuggestion,
// evidenceRefs, cohérence confidence) + validation des 3 nouveaux gisements (account_signal,
// account_fact, opportunity) et du nouveau champ relatedOpportunities (schemaVersion 2).
// Un ID renvoyé par Sonnet qui n'existe pas dans le contexte fourni (convergenceContext)
// disparaît toujours silencieusement : jamais d'exception, jamais de trust aveugle du LLM.
const digest = $input.first().json;
const top5Items = $('Pré-filtrage Déterministe').all().map((i) => i.json);
const byId = Object.fromEntries(top5Items.map((a) => [a.id, a]));

digest.articles = digest.articles.map((article) => {
  const sourceItem = byId[article.id] || {};
  const ctx = sourceItem.convergenceContext || {
    candidateIssues: [],
    candidateAccounts: [],
    candidatePlaybooks: [],
    candidateSignals: [],
    candidateFacts: [],
    candidateOpportunities: [],
  };

  let conv = article.convergences;
  if (!conv || typeof conv !== 'object' || (conv.schemaVersion !== 1 && conv.schemaVersion !== 2)) {
    conv = {
      schemaVersion: 2,
      synthesis: 'Aucune convergence identifiée ou format invalide.',
      confidence: 'low',
      matchedIssues: [],
      relatedAccounts: [],
      relatedOpportunities: [],
      playbookSuggestion: null,
      recommendedActions: [],
      evidenceRefs: [],
    };
  }

  const validIssueIds = new Set((ctx.candidateIssues || []).map((i) => i.id));
  const validAccountIds = new Set((ctx.candidateAccounts || []).map((c) => c.id));
  const validSignalIds = new Set((ctx.candidateSignals || []).map((s) => s.id));
  const validFactIds = new Set((ctx.candidateFacts || []).map((f) => f.id));
  const validOpportunityIds = new Set((ctx.candidateOpportunities || []).map((o) => o.id));
  const validPlaybookMacroIds = new Set((ctx.candidatePlaybooks || []).map((p) => p.macro_id));
  const validPlaybookSegmentIds = new Set((ctx.candidatePlaybooks || []).map((p) => p.segment_id || p.sector_id));

  // 1. Enjeux (matchedIssues)
  conv.matchedIssues = (conv.matchedIssues || []).filter((issue) => validIssueIds.has(issue.issueId)).slice(0, 3);

  // 2. Comptes (relatedAccounts)
  conv.relatedAccounts = (conv.relatedAccounts || []).filter((acc) => validAccountIds.has(acc.companyId)).slice(0, 5);

  // 3. Opportunités (relatedOpportunities, schemaVersion 2) — un compte hors du candidate
  // set ou une opportunité inventée disparaît ; ne jamais promouvoir un ID en dehors du
  // contexte fourni au modèle.
  conv.relatedOpportunities = (conv.relatedOpportunities || [])
    .filter((opp) => validOpportunityIds.has(opp.opportunityId) && validAccountIds.has(opp.companyId))
    .slice(0, 3);

  // 4. Playbook
  if (conv.playbookSuggestion) {
    const sId = conv.playbookSuggestion.sectorId;
    if (!validPlaybookMacroIds.has(sId) && !validPlaybookSegmentIds.has(sId)) {
      conv.playbookSuggestion = null;
    }
  }

  // 5. evidenceRefs (anti-hallucination d'IDs KREDO, tous gisements confondus)
  conv.evidenceRefs = (conv.evidenceRefs || []).filter((ref) => {
    if (!ref || typeof ref !== 'object' || !ref.id) return false;
    if (ref.type === 'account_issue') return validIssueIds.has(ref.id);
    if (ref.type === 'company') return validAccountIds.has(ref.id);
    if (ref.type === 'sector_playbook') return validPlaybookMacroIds.has(ref.id) || validPlaybookSegmentIds.has(ref.id);
    if (ref.type === 'account_signal') return validSignalIds.has(ref.id);
    if (ref.type === 'account_fact') return validFactIds.has(ref.id);
    if (ref.type === 'opportunity') return validOpportunityIds.has(ref.id);
    return true; // 'article' ou tout autre type générique non métier
  });

  // 6. Limite Actions
  conv.recommendedActions = (conv.recommendedActions || []).slice(0, 3);

  // 7. Règle de cohérence confidence : une confidence high/medium exige au moins 1
  // élément structuré réellement convergent (issue, compte, opportunité ou playbook).
  const hasStructuredConvergence =
    (conv.matchedIssues && conv.matchedIssues.length > 0) ||
    (conv.relatedAccounts && conv.relatedAccounts.length > 0) ||
    (conv.relatedOpportunities && conv.relatedOpportunities.length > 0) ||
    conv.playbookSuggestion !== null;

  if ((conv.confidence === 'high' || conv.confidence === 'medium') && !hasStructuredConvergence) {
    conv.confidence = 'low';
  }

  article.convergences = conv;
  return article;
});

return [{ json: digest }];

const item = $input.first().json;
return [
  {
    json: {
      status: "no_qualifying_articles",
      candidateCount: item.candidateCount || 0,
      selectedCount: 0,
      digestUpdated: false,
    },
  },
];
